// 嘉立创EDA专业版 独立脚本：多层图层 1:1 放置（工艺路线：彩印+沉金混合（暗区露铜·背光））
// 用法：PCB 编辑器 →「高级」→「运行脚本」→ 粘贴本文件全部内容 → 运行。
// 单位：EDA PCB 数据单位为 mil，1 mm = 39.3700787 mil；已按 54×85.6 mm 换算。
// 层号：1=顶层铜  5=顶层阻焊  6=底层阻焊  3=顶层丝印（彩色位图）。
// 极性：黑=有图元。铜层黑=留铜，阻焊层黑=开窗；四角含对齐锚点，保证各层 1:1 重合。
// 下单建议：哑白阻焊 · 沉金ENIG · 板厚1.6mm · 最小线宽≥0.15mm
(async function(){
  var X = 1000, Y = 1000;   // 左上角坐标(mil)，可改
  var WIDTH = 2125.9842, HEIGHT = 3370.0787;  // 54×85.6 mm
  var PW = 638, PH = 1011;   // 源图像素尺寸
  var TOL = 0.10, SIMP = 0.20;   // 矢量化容差/简化(0~1)
  function duToBlob(dataUrl){
    var p = dataUrl.split(","); var m = p[0].match(/:(.*?);/); var mime = m ? m[1] : "image/png";
    var bin = atob(p[1]); var n = bin.length; var arr = new Uint8Array(n);
    for(var i=0;i<n;i++) arr[i]=bin.charCodeAt(i);
    return new Blob([arr], {type:mime});
  }
  async function placeVec(dataUrl, layer){
    var blob = duToBlob(dataUrl);
    var cp = await eda.pcb_MathPolygon.convertImageToComplexPolygon(blob, PW, PH, TOL, SIMP, 0, 0, true, false);
    return eda.pcb_PrimitiveImage.create(X, Y, cp, layer, WIDTH, HEIGHT, 0, false, false);
  }
  var COPPER = "data:image/png;base64,";
  await placeVec(COPPER, 1);   // 顶层铜（黑=留铜 · 暗区）
  var MASK = "data:image/png;base64,";
  await placeVec(MASK, 5);   // 顶层阻焊（黑=开窗 · 暗区）
  var SILK = "data:image/png;base64,";
  await eda.pcb_PrimitiveObject.create(3, X, Y, SILK, WIDTH, HEIGHT, 0, false, "silk_孫悟空.png", false);   // 彩色丝印
  console.log("多层放置完成");
})();